use std::io::Write;
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP_SIZE: u32 = 256;
const MAX_BINS: u32 = 256;

const SHADER: &str = r#"
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, 256>;

var<workgroup> local_hist: array<atomic<u32>, 256>;

@compute @workgroup_size(256)
fn main(
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(local_invocation_index) lid: u32,
) {
    atomicStore(&local_hist[lid], 0u);
    workgroupBarrier();

    let i = gid.x;
    if (i < params.count) {
        let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
        let b = (a * a + a * 37u + 11u) % 40009u;
        let c = (b * 613u + 7919u) % 40009u;
        let d = (c + (i / 40000u) * 7919u) % 40009u;
        let value = d % 1000u;
        let bin = value * params.bins / 1000u;
        atomicAdd(&local_hist[bin], 1u);
    }
    workgroupBarrier();

    if (lid < params.bins) {
        let n = atomicLoad(&local_hist[lid]);
        if (n != 0u) {
            atomicAdd(&hist[lid], n);
        }
    }
}
"#;

fn parse_input(path: &str) -> Result<(u32, u32, u32), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let fields: Vec<&str> = text.split_whitespace().collect();
    if fields.len() != 3 {
        return Err(format!("expected 3 numbers in {path}, found {}", fields.len()));
    }
    let parse = |s: &str, name: &str, max: u32, min: u32| -> Result<u32, String> {
        let v: u32 = s.parse().map_err(|_| format!("invalid {name}: {s:?}"))?;
        if v < min || v > max {
            return Err(format!("{name} {v} out of range {min}..={max}"));
        }
        Ok(v)
    };
    Ok((
        parse(fields[0], "count", 4_000_000, 0)?,
        parse(fields[1], "seed", 9999, 0)?,
        parse(fields[2], "bins", MAX_BINS, 1)?,
    ))
}

fn histogram_on_gpu(count: u32, seed: u32, bins: u32) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::default();
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
        label: Some("histogram device"),
        ..Default::default()
    }))
    .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("histogram shader"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("histogram pipeline"),
        layout: None,
        module: &shader,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let params: [u32; 4] = [count, seed, bins, 0];
    let params_bytes: Vec<u8> = params.iter().flat_map(|v| v.to_le_bytes()).collect();
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: &params_bytes,
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let hist_size = u64::from(MAX_BINS) * 4;
    let hist_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("histogram"),
        contents: &vec![0u8; hist_size as usize],
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
    });
    let readback_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: hist_size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("histogram bind group"),
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: hist_buf.as_entire_binding(),
            },
        ],
    });

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("histogram encoder"),
    });
    let workgroups = count.div_ceil(WORKGROUP_SIZE);
    if workgroups > 0 {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("histogram pass"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(workgroups, 1, 1);
    }
    encoder.copy_buffer_to_buffer(&hist_buf, 0, &readback_buf, 0, hist_size);
    queue.submit(Some(encoder.finish()));

    let slice = readback_buf.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback dropped: {e}"))?
        .map_err(|e| format!("cannot map readback buffer: {e}"))?;

    let data = slice.get_mapped_range();
    let counts: Vec<u32> = data
        .chunks_exact(4)
        .take(bins as usize)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    drop(data);
    readback_buf.unmap();
    Ok(counts)
}

fn run() -> Result<(), String> {
    let path = std::env::args()
        .nth(1)
        .ok_or_else(|| "usage: gpu-histogram <input-file>".to_string())?;
    let (count, seed, bins) = parse_input(&path)?;
    let counts = histogram_on_gpu(count, seed, bins)?;

    let total: u64 = counts.iter().map(|&c| u64::from(c)).sum();
    if total != u64::from(count) {
        return Err(format!("GPU counted {total} values, expected {count}"));
    }

    let mut out = String::new();
    for (i, c) in counts.iter().enumerate() {
        out.push_str(&format!("BIN {i} {c}\n"));
    }
    out.push_str(&format!("TOTAL {count}\n"));
    let mut stdout = std::io::stdout().lock();
    stdout
        .write_all(out.as_bytes())
        .and_then(|_| stdout.flush())
        .map_err(|e| format!("cannot write output: {e}"))
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

